(()=>{
 const benefits={swing:['Your swing comes first.','Start with your current clubs, your goals and your budget. Compare the options against how you actually swing.'],data:['See the difference.','Launch monitor feedback helps compare launch, spin, carry and consistency. Understand how each change affects your shots before making an equipment decision.'],people:['Local expertise.','Work with AVID fitters Tyler Polanski and Colin McMahon in a comfortable indoor setting. Ask questions, test options and leave with a clear direction.']};
 document.querySelectorAll('[data-benefit]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-benefit]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const [title,copy]=benefits[button.dataset.benefit];const panel=document.querySelector('#benefit-copy');panel.querySelector('h3').textContent=title;panel.querySelector('p').textContent=copy}));
 document.querySelectorAll('[data-event-choice]').forEach(link=>link.addEventListener('click',()=>{const field=document.querySelector('#event-form select[name=eventType]');if(field)field.value=link.dataset.eventChoice}));
 const brands=document.querySelector('#fitting-brands');
 const logos={'PING':['assets/ping.svg','PING'],'Cobra':['assets/cobra.svg','Cobra Golf'],'L.A.B. Golf':['assets/lab-golf.svg','L.A.B. Golf']};
 if(brands){[...brands.children].forEach(tile=>{const name=tile.textContent,logo=logos[name];if(!logo)return;tile.replaceChildren();const img=document.createElement('img');img.src=logo[0];img.alt=logo[1];img.width=190;img.height=65;tile.append(img);if(name==='L.A.B. Golf')tile.classList.add('lab-brand')})}
 const demos=document.querySelector('#demo-days');
 if(demos&&window.AVID_CONTENT?.demoDays?.length){demos.querySelectorAll('article').forEach(article=>{article.classList.add('demo-event');const date=article.querySelector('.eyebrow');if(date){const plaque=document.createElement('div');plaque.className='date-plaque';const label=document.createElement('span');label.textContent='DEMO DAY';plaque.append(label,date);const content=document.createElement('div');while(article.firstChild)content.append(article.firstChild);article.append(plaque,content)}})}
})();
